ai-watermarking.pseudocode:
def is_green(prev_tok, tok, key, gamma=0.5):
    # 이전 토큰 + 비밀키로 어휘를 재현 가능하게 분할
    return prf(key, prev_tok, tok) < gamma  # prf: 0~1 값

def generate_step(logits, prev_tok, key, delta=2.0):
    for tok in range(len(logits)):
        if is_green(prev_tok, tok, key):
            logits[tok] += delta  # 그린 토큰 선호
    return sample(softmax(logits))

def detect(tokens, key, gamma=0.5):
    T = len(tokens) - 1
    g = sum(is_green(tokens[i - 1], tokens[i], key)
            for i in range(1, len(tokens)))
    # 그린 토큰 비율이 우연(γ)보다 유의하게 높은가
    z = (g - gamma * T) / sqrt(T * gamma * (1 - gamma))
    return z > 4.0  # 워터마크(AI 생성)로 판정
